#!/usr/bin/env node
// Bundles the two worker source files into one pasteable file.
//
//   node scripts/build-worker-bundle.mjs   ->  stockroom/worker-bundled.js
//
// The Cloudflare dashboard's code editor takes a single file, while the real
// worker is split across site-cdn-worker.js and stockroom.js. This produces a
// single-file build for people deploying by clicking rather than with wrangler.
//
// Deploying with wrangler does not need this at all.

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (file) => readFileSync(path.join(ROOT, file), 'utf8');

let stockroom = read('worker/stockroom.js');
let edge = read('worker/site-cdn-worker.js');

// Drop the import — both halves end up in the same module.
const IMPORT = /^import\s*\{[^}]*\}\s*from\s*['"]\.\/stockroom\.js['"];?\n/m;
if (!IMPORT.test(edge)) {
  console.error('Could not find the stockroom.js import in site-cdn-worker.js.');
  console.error('The bundler is out of step with the source — fix the pattern above.');
  process.exit(1);
}
edge = edge.replace(IMPORT, '');

// Named exports exist for the tests; a worker only needs its default export.
stockroom = stockroom.replace(/^export\s+(async\s+function|function)/gm, '$1');

const bundle = `// ESNTLS site edge worker + STOCKROOM api — SINGLE FILE BUILD.
//
// Generated by scripts/build-worker-bundle.mjs from:
//   worker/site-cdn-worker.js
//   worker/stockroom.js
//
// This exists only for pasting into the Cloudflare dashboard editor, which
// takes one file. DO NOT EDIT THIS DIRECTLY — edit the two sources above and
// run the script again, or deploy with wrangler and ignore this file.

${stockroom}

${edge}`;

writeFileSync(path.join(ROOT, 'stockroom/worker-bundled.js'), bundle);

// Guard against the two halves drifting apart and producing a broken paste.
const leftoverImports = bundle.match(/^import\s/gm) || [];
const defaultExports = bundle.match(/^export default/gm) || [];
if (leftoverImports.length || defaultExports.length !== 1) {
  console.error(`Bundle looks wrong: ${leftoverImports.length} imports, ${defaultExports.length} default exports.`);
  process.exit(1);
}

console.log(`stockroom/worker-bundled.js written — ${Math.round(bundle.length / 1024)}KB, ready to paste.`);
